/**
 * A single keyboard key, drawn as a keycap (`design/components/kbd.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/kbd.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation } from '@angular/core'

import { MEMBER_PROVIDERS, SlotOutlet, SlotTemplate, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/kbd.module.css'

/** A single keyboard key, drawn as a keycap: the inputs it takes, by the React member's prop names. */
export type KbdProps = Record<string, never>

/** A single keyboard key, drawn as a keycap. */
@Component({
  selector: 'pm-kbd',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<kbd
[attr.class]="e1()"
data-member="kbd"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></kbd>`,
})
export class Kbd {
  protected readonly $ = useMember({ events: [], props: {} })
  protected readonly $p = this.$.props

  protected e1() {
    return styles.kbd
  }
}
